package net.neoforged.neoforge.registries;import java.util.*;import java.util.function.Supplier;public class DeferredRegister{public static Map<String,Holder> entries=new LinkedHashMap<>();public static boolean subscribed;public static DeferredRegister create(Object registry,String namespace){entries.clear();return new DeferredRegister();}public Holder register(String name,Supplier<?> supplier){var h=new Holder(supplier);entries.put(name,h);return h;}public void register(Object bus){subscribed=true;}public static class Holder{Supplier<?> value;Object cached;Holder(Supplier<?> value){this.value=value;}public Object get(){if(cached==null)cached=value.get();return cached;}}}
